#!/usr/bin/env node
// bpmn: {"file":"user-story-refinement.bpmn","elements":["StoreRef_BacklogTriage","StoreRef_BacklogFreigabe"]}
//
// Claude Code PreToolUse hook, generated by bpmn2agent-generate from the live data stores
// "Product Backlog & User Story Map" and "Product Backlog: freigegebene Änderungen" in
// user-story-refinement.bpmn. Backs up the diagram's approval steps: every gh call that is not a
// known read makes Claude Code ask the human at the call (permissionDecision "ask"), even if a skill
// forgot the approval. Reads and every other tool pass untouched. CLAUDE-ONLY: hooks are a Claude
// Code mechanism.
//
// The command is split on shell operators (; && || | newline $( ) backticks) and gh is looked for in
// every segment, also after env assignments, env/command/exec, as a path ending in /gh, or inside
// bash -c / sh -c (quotes are ignored, so the inner command is split too). A segment counts as a read
// only when its gh subcommand is in READS; anything else, including gh api and flags before the
// subcommand, counts as a write. The hook does not pin repo or project: the skills pass -R/--owner and
// the approval steps show the target.
//
// Reads the PreToolUse hook JSON on stdin. Prints the decision JSON on stdout and exits 0 when the
// call may write into the backlog; prints nothing and exits 0 otherwise.

// Read patterns from contextSources.*.tools.read (Bash(gh <sub>:*)).
const READS = [
  'auth status', 'issue list', 'issue view', 'search issues',
  'project view', 'project item-list', 'project field-list',
];

// One entry per live store with tools.write.
const STORES = [
  {
    name: 'Product Backlog & User Story Map',
    approval: 'Änderungshinweis an offene Story freigeben / Parken im Opportunity Backlog freigeben',
    bash: ['gh issue comment', 'gh issue create'],
  },
  {
    name: 'Product Backlog: freigegebene Änderungen',
    approval: 'Zusammenführung freigeben / Story priorisieren & Übernahme ins Backlog freigeben',
    bash: ['gh issue create', 'gh issue edit', 'gh issue comment', 'gh project item-add', 'gh project item-edit'],
  },
];

const input = JSON.parse(await new Response(process.stdin).text());
if (input.tool_name !== 'Bash') process.exit(0);
const command = String(input.tool_input?.command ?? '');

const isGh = (t) => t === 'gh' || t.endsWith('/gh');
const writes = [];
for (const segment of command.split(/;|&&|\|\||\||\n|\$\(|\)|`/)) {
  const tokens = segment.replace(/["']/g, ' ').trim().split(/\s+/).filter(Boolean);
  const i = tokens.findIndex(isGh);
  if (i === -1) continue;
  const sub = tokens.slice(i + 1, i + 3).join(' ');
  if (!READS.includes(sub)) writes.push(`gh ${sub}`.trim());
}

if (writes.length) {
  const hit = STORES.filter((s) => writes.some((w) => s.bash.includes(w)));
  const stores = (hit.length ? hit : STORES);
  console.log(JSON.stringify({
    hookSpecificOutput: {
      hookEventName: 'PreToolUse',
      permissionDecision: 'ask',
      permissionDecisionReason:
        `"${writes.join('", "')}" may write into ${stores.map((s) => `"${s.name}"`).join(' / ')}; ` +
        `needs approval (step "${stores.map((s) => s.approval).join(' / ')}")`,
    },
  }));
}
process.exit(0);
